    # AI coding tools.
    "CLAUDECODE": "claude-code",
    "CURSOR_TRACE_ID": "cursor",
    "LANGCHAIN_TRACING_V2": "langchain",
    "LANGSMITH_API_KEY": "langchain",
    "LANGGRAPH_API_URL": "langgraph",
    # CI systems.
    "GITHUB_ACTIONS": "github-actions",
    "JENKINS_URL": "jenkins",
}

# Process names that indicate an interactive terminal shell.
_SHELL_NAMES = frozenset(
    ["bash", "zsh", "fish", "sh", "dash", "tcsh", "ksh"]
)

# Values of the CI env var that count as "truthy" for CI detection.
_CI_TRUTHY_VALUES = frozenset(["true", "1", "yes"])

# Timeout for the small `ps`/subprocess calls used during process inspection.
_SUBPROCESS_TIMEOUT_SECONDS = 2


def _match_signatures(env_text: str) -> Optional[str]:
    """Return the label of the first signature present in ``env_text``.

    ``env_text`` is a string of environment variables separated by spaces or
    newlines. Bare signature keys match on ``f"{key}="`` presence; keys that
    contain ``"="`` are matched as an exact substring.
    """
    for signature, label in _CALLER_SIGNATURES.items():
        if "=" in signature:
            if signature in env_text:
                return label
        elif f"{signature}=" in env_text:
            return label
    return None


def _read_parent_env_linux(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` from ``/proc``.

    Null byte separators are replaced with newlines to yield a printable,
    newline-separated env string. Returns ``None`` if the process env cannot
    be read.
    """
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            raw = f.read()
    except (PermissionError, FileNotFoundError):
        return None
    return raw.replace(b"\0", b"\n").decode("utf-8", errors="replace")


def _read_parent_env_macos(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` on macOS via ``ps eww``.

    Returns the command stdout when it exits successfully, otherwise ``None``.
    """
    try:
        result = subprocess.run(
            ["ps", "eww", "-p", str(ppid), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout


def _get_full_command(pid: int) -> Optional[str]:
    """Return the full command line of ``pid`` (stripped), or ``None``."""
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def _get_process_name(pid: int) -> Optional[str]:
    """Return the basename of the command name for ``pid``.

    Gradle daemons run as ``java`` but are identified by inspecting the full
    command line for the ``GradleDaemon`` marker.
    """
