        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "comm="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    name = os.path.basename(result.stdout.strip())
    if name == "java":
        full_command = _get_full_command(pid)
        if full_command and "GradleDaemon" in full_command:
            return "gradle"
    return name


def _get_parent_pid(pid: int) -> Optional[int]:
    """Return the parent PID of ``pid``, or ``None`` at the top of the tree."""
    if pid == 1:
        return None
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "ppid="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT_SECONDS,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    try:
        return int(result.stdout.strip())
    except ValueError:
        return None


def _get_ancestor_chain(max_depth: int = 4) -> List[str]:
    """Return process names walking up from the current process's parent."""
    chain: List[str] = []
    pid: Optional[int] = os.getppid()
    while pid is not None and len(chain) < max_depth:
        name = _get_process_name(pid)
        if name is None:
            break
        chain.append(name)
        pid = _get_parent_pid(pid)
    return chain


def _identify_caller_inner() -> str:
    """Perform tiered caller detection. May raise; wrapped by identify_caller."""
    # Tier 1: explicit override.
    override = os.environ.get("DATAHUB_CALLER")
    if override:
        return override

    # Tier 2: known signatures in our own environment.
    for signature, label in _CALLER_SIGNATURES.items():
        if "=" in signature:
            key, _, value = signature.partition("=")
            if os.environ.get(key) == value:
                return label
        elif os.environ.get(signature):
            return label

    # Tier 3 (part of Tier 2 ordering): generic CI signal.
    ci_value = os.environ.get("CI")
    if ci_value and ci_value.lower() in _CI_TRUTHY_VALUES:
        return "ci"

    # Tier 3: parent process environment.
    ppid = os.getppid()
    system = platform.system()
    if system == "Linux":
        parent_env = _read_parent_env_linux(ppid)
    elif system == "Darwin":
        parent_env = _read_parent_env_macos(ppid)
    else:
        parent_env = None
    if parent_env:
        match = _match_signatures(parent_env)
        if match:
            return match

    # Tier 4: process-tree heuristics.
    chain = _get_ancestor_chain()
    lowered = [name.lower() for name in chain]
    if any("cursor" in name for name in lowered):
        return "cursor"
    if any("claude" in name for name in lowered):
        return "claude-code"
    if not chain:
        return "unknown"
    first = chain[0]
    if first.lower() in _SHELL_NAMES:
        return "terminal"
    return first


